import * as THREE from 'three/webgpu';
import { MeshPhysicalMaterial, MeshStandardMaterial, MeshBasicMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Procedural pedestal + torus‑knot material study.
 * All resources are created synchronously using the provided context loaders.
 */
export default function createNode(config, ctx) {
  // -------------------------------------------------------------------------
  // Helpers to create simple DataTexture gradients (no DOM usage)
  // -------------------------------------------------------------------------
  function createRadialAlphaTexture(size, innerAlpha, outerAlpha) {
    const data = new Uint8Array(size * size);
    const half = size / 2;
    const maxDist = half;
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const dx = x - half;
        const dy = y - half;
        const dist = Math.sqrt(dx * dx + dy * dy) / maxDist; // 0‑1
        const a = THREE.MathUtils.clamp(
          THREE.MathUtils.mapLinear(dist, 0, 0.4, innerAlpha, outerAlpha),
          0,
          1
        );
        data[y * size + x] = Math.round(a * 255);
      }
    }
    const tex = new THREE.DataTexture(data, size, size, THREE.AlphaFormat);
    tex.needsUpdate = true;
    tex.minFilter = tex.magFilter = THREE.LinearFilter;
    tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
    tex.generateMipmaps = false;
    return tex;
  }

  function createVerticalGradientTexture(width, height, stops) {
    // stops: [{at:0,hex:'#...'}...]
    const data = new Uint8Array(width * height * 3);
    for (let y = 0; y < height; y++) {
      const v = y / (height - 1);
      // find two surrounding stops
      let lower = stops[0];
      let upper = stops[stops.length - 1];
      for (let i = 0; i < stops.length - 1; i++) {
        if (v >= stops[i].at && v <= stops[i + 1].at) {
          lower = stops[i];
          upper = stops[i + 1];
          break;
        }
      }
      const range = upper.at - lower.at;
      const t = range === 0 ? 0 : (v - lower.at) / range;
      const c1 = new THREE.Color(lower.hex);
      const c2 = new THREE.Color(upper.hex);
      const c = c1.lerp(c2, t);
      const i = y * width * 3;
      data[i] = Math.round(c.r * 255);
      data[i + 1] = Math.round(c.g * 255);
      data[i + 2] = Math.round(c.b * 255);
    }
    const tex = new THREE.DataTexture(data, width, height, THREE.RGBFormat);
    tex.needsUpdate = true;
    tex.minFilter = tex.magFilter = THREE.LinearFilter;
    tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
    tex.generateMipmaps = false;
    return tex;
  }

  // -------------------------------------------------------------------------
  // Load assets
  // -------------------------------------------------------------------------
  const brushedTex = ctx.textureLoader('/prism-assets/chrome/brushed-metal.map.png');
  brushedTex.wrapS = brushedTex.wrapT = THREE.RepeatWrapping;

  // -------------------------------------------------------------------------
  // Create materials
  // -------------------------------------------------------------------------
  const pedestalMat = new MeshStandardMaterial({
    color: new THREE.Color('#14141a'),
    metalness: 0.35,
    roughness: 0.7,
  });

  const knotMat = new MeshPhysicalMaterial({
    color: new THREE.Color('#16161d'),
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    roughnessMap: brushedTex,
    // per‑spec jitter of 2 % on roughness
    roughness: 0.55 + (Math.random() - 0.5) * 0.02,
  });

  const shadowTex = createRadialAlphaTexture(256, 0.6, 0.0);
  const shadowMat = new MeshBasicMaterial({
    map: shadowTex,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });

  const backdropStops = [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const backdropTex = createVerticalGradientTexture(256, 256, backdropStops);
  const backdropMat = new MeshBasicMaterial({
    map: backdropTex,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // -------------------------------------------------------------------------
  // Geometries
  // -------------------------------------------------------------------------
  const pedestalGeo = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 64);
  const knotGeo = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);
  const shadowGeo = new THREE.PlaneGeometry(3, 3);
  const backdropGeo = new THREE.PlaneGeometry(7, 6);

  // -------------------------------------------------------------------------
  // Meshes
  // -------------------------------------------------------------------------
  const group = new THREE.Group();

  const pedestal = new THREE.Mesh(pedestalGeo, pedestalMat);
  // top face at y = -0.35 → center y = -0.35 - 0.25
  pedestal.position.set(0, -0.60, 0);
  group.add(pedestal);

  const knot = new THREE.Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  group.add(knot);

  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.36, 0);
  group.add(shadow);

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  // plane faces +z by default; keep that orientation
  group.add(backdrop);

  // -------------------------------------------------------------------------
  // Text (MSDF via fontAtlas)
  // -------------------------------------------------------------------------
  // Headline
  const headline = ctx.fontAtlas.createText({
    string: 'Material study 03',
    fontSize: 68,
    fontWeight: 600,
    fontFamily: 'Lora',
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headline.position.set(0, -1.2, 0);
  group.add(headline);

  // Caption
  const caption = ctx.fontAtlas.createText({
    string: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT',
    fontSize: 18,
    fontWeight: 400,
    fontFamily: 'JetBrains Mono',
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#e8ecf2',
  });
  caption.position.set(0, -1.6, 0);
  group.add(caption);

  // -------------------------------------------------------------------------
  // Lighting (simple studio)
  // -------------------------------------------------------------------------
  const hemi = new THREE.HemisphereLight(0xffffff, 0x444444, 1);
  hemi.position.set(0, 1, 0);
  group.add(hemi);

  // -------------------------------------------------------------------------
  // Apply cinematic primitives
  // -------------------------------------------------------------------------
  if (ctx.primitives && ctx.primitives.orbit) {
    ctx.primitives.orbit(group, { speed: 0.1, radius: 0.4 });
  }

  // -------------------------------------------------------------------------
  // UserData – handlers placeholder and cleanup
  // -------------------------------------------------------------------------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    // Dispose geometries
    pedestalGeo.dispose();
    knotGeo.dispose();
    shadowGeo.dispose();
    backdropGeo.dispose();

    // Dispose materials
    pedestalMat.dispose();
    knotMat.dispose();
    shadowMat.dispose();
    backdropMat.dispose();

    // Dispose textures
    brushedTex.dispose();
    shadowTex.dispose();
    backdropTex.dispose();

    // Dispose any GSAP timelines (none created directly here)
    gsap.globalTimeline.clear();
  };

  // Position/rotation/scale from spec (already default)
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  return group;
}
